"use strict";
let loggedIn = !1;
const loginForm = document.getElementById("loginForm"),
  login = "ptyc",
  password = "ptyc123",
  loginInput = document.getElementById("username"),
  passwordInput = document.getElementById("password"),
  errorDiv = document.getElementById("errorDiv"),
  pl = document.getElementById("pl"),
  eng = document.getElementById("eng"),
  loginButton = document.getElementById("loginButton"),
  x_close = document.getElementsByClassName("x-close")[0];
function addDisplayNone() {
  errorDiv.style.display = "none";
}
function showLoginForm() {
  (loggedIn =
    loginInput.value === login && passwordInput.value === password
      ? !0
      : loggedIn)
    ? pl.checked && eng.checked
      ? (pl.checked = !1)
      : pl.checked
      ? (window.location.href = "pl.html")
      : eng.checked && (window.location.href = "eng.html")
    : (errorDiv.style.display = "block"),
    pl.addEventListener("click", function () {
      pl.checked && eng.checked && (eng.checked = !1);
    }),
    eng.addEventListener("click", function () {
      pl.checked && eng.checked && (pl.checked = !1);
    });
}
function checkCheckboxStatePl() {
  pl.checked && (eng.checked = !1);
}
function checkCheckboxStateEng() {
  eng.checked && (pl.checked = !1);
}
loginButton.addEventListener("click", showLoginForm),
  pl.addEventListener("click", checkCheckboxStatePl),
  eng.addEventListener("click", checkCheckboxStateEng),
  x_close.addEventListener("click", addDisplayNone);

document.addEventListener("DOMContentLoaded", () => {
  const button = document.getElementById("loginButton");

  button.addEventListener("click", function (e) {
    const circle = document.createElement("span");
    const rect = this.getBoundingClientRect();
    const diameter = Math.max(this.clientWidth, this.clientHeight);
    const radius = diameter / 2;

    circle.style.width = circle.style.height = `${diameter}px`;
    circle.style.left = `${e.clientX - rect.left - radius}px`;
    circle.style.top = `${e.clientY - rect.top - radius}px`;
    circle.classList.add("ripple");

    const ripple = this.getElementsByClassName("ripple")[0];
    if (ripple) ripple.remove();

    this.appendChild(circle);
  });
});
